// Block (composition) — a full-width page-level notice built on Alert.
// Alert owns notice semantics and look; Stack only arranges optional actions.
import type { ReactNode } from "react";
import { Alert } from "../components/Alert";
import type { AlertLive, AlertVariant } from "../components/Alert";
import { Button } from "../components/Button";
import { Stack } from "../layouts/Stack";
import "./Banner.css";

export interface BannerProps {
  /** Alert 의 축을 그대로 쓴다 — 손으로 베낀 유니온은 Alert 이 값을 늘려도 조용히 좁아진다. */
  variant?: AlertVariant;
  /**
   * Announcement urgency, forwarded to `Alert`. Deliberately **not** derived from `variant` — a
   * red banner is not automatically "stop reading and listen to this".
   *
   * Left undefined a banner inherits Alert's `polite` default, which is the honest choice for the
   * usual case: a page-level notice that is already on screen at first paint is not reliably
   * announced at all (a live region has to exist *before* its content arrives), so claiming
   * `assertive` would promise an interruption the browser never delivers. Pass `assertive`
   * only for a banner that appears in response to something the user just did.
   */
  live?: AlertLive;
  title?: string;
  children: ReactNode;
  action?: ReactNode;
  onDismiss?: () => void;
  className?: string;
}

export function Banner({
  variant = "info",
  live,
  title,
  children,
  action,
  onDismiss,
  className,
}: BannerProps) {
  return (
    <Alert
      variant={variant}
      live={live}
      title={title}
      className={className ? `sd-banner ${className}` : "sd-banner"}
      actions={
        (action || onDismiss) && (
          <Stack direction="row" align="center" justify="end" gap="x-small" wrap className="sd-banner__actions">
            {action}
            {onDismiss && (
              <Button type="button" variant="secondary" size="small" onPress={onDismiss}>
                Dismiss
              </Button>
            )}
          </Stack>
        )
      }
    >
      {children}
    </Alert>
  );
}

/* Banner.css — .sd-banner (Block)
   Full-width arrangement only. Alert owns all notice chrome and typography. */
.sd-banner {
  width: 100%;
}
